import{_ as e,o as a,c as i,ae as d}from"./chunks/framework.BuGep-IT.js";const y=JSON.parse('{"title":"ベンチマーク","description":"","frontmatter":{},"headers":[],"relativePath":"guide/benchmarks.md","filePath":"guide/benchmarks.md"}'),l={name:"guide/benchmarks.md"};function h(r,t,s,n,o,g){return a(),i("div",null,[...t[0]||(t[0]=[d('<h1 id="benchmarks" tabindex="-1">ベンチマーク <a class="header-anchor" href="#benchmarks" aria-label="Permalink to &quot;ベンチマーク {#benchmarks}&quot;">​</a></h1><p><code>asyncmux</code> の性能特性を、<code>benchmarks/asyncmux.bench.ts</code> による測定結果とともに示します。 ここに載せる数値は特定の環境での参考値であり、実行環境によって変動します。</p><h2 id="methodology" tabindex="-1">測定方法 <a class="header-anchor" href="#methodology" aria-label="Permalink to &quot;測定方法 {#methodology}&quot;">​</a></h2><p>測定には Vitest のベンチマーク機能を用いています。 各ケースは約 0.5 秒間繰り返し実行され、<code>ops/sec</code> は 1 秒あたりの実行回数を表します。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bench</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./.config/vitest.bench.ts</span></span></code></pre></div><p>測定環境は次のとおりです。</p><ul><li>CPU: 12th Gen Intel Core i9-12900K</li><li>メモリー: 32 GiB</li><li>Node.js: v24.15.0</li><li>測定日: 2026-09-08</li></ul><h2 id="results" tabindex="-1">測定結果 <a class="header-anchor" href="#results" aria-label="Permalink to &quot;測定結果 {#results}&quot;">​</a></h2><h3 id="uncontended" tabindex="-1">A. 競合なしのロック取得 <a class="header-anchor" href="#uncontended" aria-label="Permalink to &quot;A. 競合なしのロック取得 {#uncontended}&quot;">​</a></h3><p>待ち行列が存在しない状態での <code>lock</code> / <code>rLock</code> の取得と解放の速度です。</p><table tabindex="0"><thead><tr><th>ケース</th><th style="text-align:right;">ops/sec</th><th style="text-align:right;">平均</th><th style="text-align:right;">p99</th></tr></thead><tbody><tr><td><code>lock</code> / <code>release</code>（キーなし）</td><td style="text-align:right;">1,196,752</td><td style="text-align:right;">0.0008 ms</td><td style="text-align:right;">0.0012 ms</td></tr><tr><td><code>lock</code> / <code>release</code>（キーあり）</td><td style="text-align:right;">972,952</td><td style="text-align:right;">0.0010 ms</td><td style="text-align:right;">0.0020 ms</td></tr><tr><td><code>rLock</code> / <code>release</code>（キーなし）</td><td style="text-align:right;">1,181,629</td><td style="text-align:right;">0.0008 ms</td><td style="text-align:right;">0.0011 ms</td></tr><tr><td><code>rLock</code> / <code>release</code>（キーあり）</td><td style="text-align:right;">834,585</td><td style="text-align:right;">0.0012 ms</td><td style="text-align:right;">0.0015 ms</td></tr></tbody></table><h3 id="low-contention" tabindex="-1">B. 低い競合 <a class="header-anchor" href="#low-contention" aria-label="Permalink to &quot;B. 低い競合 {#low-contention}&quot;">​</a></h3><p>2 つのワーカーが同一キーに対して取得と解放を繰り返す場合の速度です。</p><table tabindex="0"><thead><tr><th>ケース</th><th style="text-align:right;">ops/sec</th><th style="text-align:right;">平均</th><th style="text-align:right;">p99</th></tr></thead><tbody><tr><td>2 ワーカー × 4 回操作（同一キー）</td><td style="text-align:right;">77,059</td><td style="text-align:right;">0.0130 ms</td><td style="text-align:right;">0.0144 ms</td></tr><tr><td>2 ワーカー × 16 回操作（同一キー）</td><td style="text-align:right;">24,165</td><td style="text-align:right;">0.0414 ms</td><td style="text-align:right;">0.0397 ms</td></tr></tbody></table><h3 id="high-contention" tabindex="-1">C. 高い競合 <a class="header-anchor" href="#high-contention" aria-label="Permalink to &quot;C. 高い競合 {#high-contention}&quot;">​</a></h3><p>多数の要求が同時に同一のロックへ殺到した場合の速度です。</p><table tabindex="0"><thead><tr><th>ケース</th><th style="text-align:right;">ops/sec</th><th style="text-align:right;">平均</th><th style="text-align:right;">p99</th></tr></thead><tbody><tr><td>32 件の同時要求（キーなし）</td><td style="text-align:right;">22,103</td><td style="text-align:right;">0.0452 ms</td><td style="text-align:right;">0.0425 ms</td></tr><tr><td>128 件の同時要求（同一キー）</td><td style="text-align:right;">2,011</td><td style="text-align:right;">0.4972 ms</td><td style="text-align:right;">0.5530 ms</td></tr></tbody></table><h3 id="repeated-lock-unlock" tabindex="-1">D. ロック取得と解放の繰り返し <a class="header-anchor" href="#repeated-lock-unlock" aria-label="Permalink to &quot;D. ロック取得と解放の繰り返し {#repeated-lock-unlock}&quot;">​</a></h3><p>1 つのワーカーが取得と解放を連続で繰り返す場合の速度です。</p><table tabindex="0"><thead><tr><th>ケース</th><th style="text-align:right;">ops/sec</th><th style="text-align:right;">平均</th><th style="text-align:right;">p99</th></tr></thead><tbody><tr><td>連続 16 回</td><td style="text-align:right;">59,214</td><td style="text-align:right;">0.0169 ms</td><td style="text-align:right;">0.0172 ms</td></tr><tr><td>連続 64 回</td><td style="text-align:right;">16,500</td><td style="text-align:right;">0.0606 ms</td><td style="text-align:right;">0.0582 ms</td></tr></tbody></table><h3 id="queued-operations" tabindex="-1">E. キューに溜まった要求の処理 <a class="header-anchor" href="#queued-operations" aria-label="Permalink to &quot;E. キューに溜まった要求の処理 {#queued-operations}&quot;">​</a></h3><p>保持中のロックを解放し、キューに溜めた読み書き要求を一括で流す場合の速度です。</p><table tabindex="0"><thead><tr><th>ケース</th><th style="text-align:right;">ops/sec</th><th style="text-align:right;">平均</th><th style="text-align:right;">p99</th></tr></thead><tbody><tr><td>50 件の読み書き要求を処理</td><td style="text-align:right;">13,877</td><td style="text-align:right;">0.0721 ms</td><td style="text-align:right;">0.0648 ms</td></tr><tr><td>200 件の読み書き要求を処理</td><td style="text-align:right;">3,044</td><td style="text-align:right;">0.3285 ms</td><td style="text-align:right;">7.4403 ms</td></tr></tbody></table><h3 id="error-path" tabindex="-1">F. エラー経路 <a class="header-anchor" href="#error-path" aria-label="Permalink to &quot;F. エラー経路 {#error-path}&quot;">​</a></h3><p>ロックの二重解放や、中断済みシグナルでの取得といった例外系の速度です。</p><table tabindex="0"><thead><tr><th>ケース</th><th style="text-align:right;">ops/sec</th><th style="text-align:right;">平均</th><th style="text-align:right;">p99</th></tr></thead><tbody><tr><td>二重解放（<code>LockReleasedError</code> を投げる）</td><td style="text-align:right;">222,488</td><td style="text-align:right;">0.0045 ms</td><td style="text-align:right;">0.0065 ms</td></tr><tr><td>中断済みシグナル（拒否される）</td><td style="text-align:right;">159,919</td><td style="text-align:right;">0.0063 ms</td><td style="text-align:right;">0.0068 ms</td></tr></tbody></table><h3 id="cancellation" tabindex="-1">G. 待機の取り消し <a class="header-anchor" href="#cancellation" aria-label="Permalink to &quot;G. 待機の取り消し {#cancellation}&quot;">​</a></h3><p>キューで待機中の取得を <code>AbortSignal</code> で取り消す場合の速度です。</p><table tabindex="0"><thead><tr><th>ケース</th><th style="text-align:right;">ops/sec</th><th style="text-align:right;">平均</th><th style="text-align:right;">p99</th></tr></thead><tbody><tr><td>待機中の取り消し</td><td style="text-align:right;">106,592</td><td style="text-align:right;">0.0094 ms</td><td style="text-align:right;">0.0087 ms</td></tr></tbody></table><h3 id="realistic-workload" tabindex="-1">H. 現実的な負荷 <a class="header-anchor" href="#realistic-workload" aria-label="Permalink to &quot;H. 現実的な負荷 {#realistic-workload}&quot;">​</a></h3><p>読み取り 12 件と書き込み 3 件に全体ロック 1 件を混ぜた、キャッシュアクセスを模した負荷での速度です。</p><table tabindex="0"><thead><tr><th>ケース</th><th style="text-align:right;">ops/sec</th><th style="text-align:right;">平均</th><th style="text-align:right;">p99</th></tr></thead><tbody><tr><td>読み書き混在アクセス（12R ＋ 3W ＋全体 W）</td><td style="text-align:right;">43,378</td><td style="text-align:right;">0.0231 ms</td><td style="text-align:right;">0.0230 ms</td></tr></tbody></table><h2 id="how-to-read" tabindex="-1">結果の読み方 <a class="header-anchor" href="#how-to-read" aria-label="Permalink to &quot;結果の読み方 {#how-to-read}&quot;">​</a></h2><p>競合なしのロック取得は 100 万 ops/sec を超えており、通常の非同期処理に付随する排他制御の負荷は無視できる水準にあります。 読み取りロックと書き込みロックの間に大きな速度差はなく、キー指定の有無も結果を大きく変えません。 128 件が同時に殺到するような高い競合下でも 1 件あたり 0.5 ms 程度で処理でき、読み書き混在の現実的な負荷では 4 万 ops/sec を超えています。</p>',34)])])}const x=e(l,[["render",h]]);export{y as __pageData,x as default};
